{"source": "def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        table = {}
        committed = {}
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        in_tx = False
        tx_snapshot = None

        def do_write(conn, op, key, value):
            nonlocal main_changes, other_changes, main_total, other_total
            changed = 0
            if op == "put":
                if key in table:
                    if put_mode == "ignore":
                        changed = 0
                    else:
                        table[key] = value
                        changed = 1
                else:
                    table[key] = value
                    changed = 1
            elif op == "update":
                if key in table:
                    table[key] = value
                    changed = 1
            elif op == "delete":
                if key in table:
                    del table[key]
                    changed = 1
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_changes = changed
                other_total += changed

        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            key = action.get("key")
            value = action.get("value")
            if op == "begin":
                if not in_tx:
                    in_tx = True
                    tx_snapshot = (dict(table), dict(committed), main_changes, other_changes, main_total, other_total)
            elif op == "commit":
                if in_tx:
                    committed = dict(table)
                    in_tx = False
                    tx_snapshot = None
            elif op == "rollback":
                if in_tx:
                    table, committed, main_changes, other_changes, main_total, other_total = tx_snapshot
                    in_tx = False
                    tx_snapshot = None
            else:
                do_write(conn, op, key, value)

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total":
            channel = main_total
        else:
            channel = main_total + other_total
        return channel, len(committed), sum(committed.values())

    def consistent(put_mode, trigger, channel_mode):
        for receipt in history:
            actions = receipt.get("actions", [])
            observed = receipt.get("observed", {})
            ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
            if ch != observed.get("channel"):
                return False
            if cc != observed.get("committed_count"):
                return False
            if cs != observed.get("committed_sum"):
                return False
        return True

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trigger in (False, True):
            for channel_mode in ("changes", "total", "both"):
                if consistent(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            values.append(ch)
        elif goal == "committed_count":
            values.append(cc)
        elif goal == "committed_sum":
            values.append(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Disposable SQLite sources from the disclosed 18-member family, actions limited to put, update, delete, begin, commit, rollback on main or other connections, goals limited to channel, committed_count, or committed_sum.", "lesson": "The prior simulator was wrong in three coupled ways: it treated the two connections as separate key spaces, modeled changes() as a running counter, and ignored the trigger's effect on the channel. The corrected model uses one shared items table, resets the per-statement changes() count on every write, and treats the channel as the value of the chosen counter after the final action. The receipts are consistent with put_mode=ignore, no trigger, and channel=changes(): the first receipt ends with a delete of an existing row (changes=1), the second and third end with rollback (changes=0), and the fourth ends with a commit (changes=0). Committed state is the shared table after applying committed transactions."}
